#!/system/bin/sh
APK="$1"; [ -f "$APK" ] || exit 1; TMP="${TMPDIR:-$(dirname "$APK")}/msa72_matrix_$$"; unzip -p "$APK" 'classes*.dex' 2>/dev/null|strings > "$TMP"; echo '=== APK ENGINEERING MATRIX ==='; for row in 'Decode:apktool|decode_' 'Rebuild:build apk|aapt2|zipalign' 'DEX:dexlib2|smali|baksmali' 'Decompiler:jadx|JadxDecompiler' 'Signing:ApkSigner|apksigner|keystore'; do n=${row%%:*}; p=${row#*:}; c=$(grep -Eic "$p" "$TMP"); [ "$c" -gt 20 ]&&s='VERY HIGH'||{ [ "$c" -gt 4 ]&&s='HIGH'||{ [ "$c" -gt 0 ]&&s='PRESENT'||s='LOW'; }; }; printf '%-12s %-10s (%s refs)\n' "$n" "$s" "$c"; done; rm -f "$TMP"
